// The synthetic invoice PDFs as bytes inside workerd, which has no file system: Vite inlines each
// file as a data URL (test/fixtures/pdf-forensics/load.ts does the same). Generated by
// scripts/fixtures/make-invoices.ts (D06 T01 §5); labels in labels.json beside them.
import fynbosAccount from "./fynbos-cleaning-account.pdf?inline";
import fynbosDomain from "./fynbos-cleaning-domain.pdf?inline";
import fynbosGenuine from "./fynbos-cleaning-genuine.pdf?inline";
import fynbosLetter from "./fynbos-cleaning-letter.pdf?inline";
import hadedaAccount from "./hadeda-couriers-account.pdf?inline";
import hadedaDomain from "./hadeda-couriers-domain.pdf?inline";
import hadedaGenuine from "./hadeda-couriers-genuine.pdf?inline";
import hadedaLetter from "./hadeda-couriers-letter.pdf?inline";
import karooAccount from "./karoo-stationery-account.pdf?inline";
import karooDomain from "./karoo-stationery-domain.pdf?inline";
import karooGenuine from "./karoo-stationery-genuine.pdf?inline";
import karooLetter from "./karoo-stationery-letter.pdf?inline";

const bytes = (dataUrl: string) =>
  Uint8Array.from(atob(dataUrl.slice(dataUrl.indexOf(",") + 1)), (c) => c.charCodeAt(0));

export const invoicePdfs: Record<string, Uint8Array> = {
  "fynbos-cleaning-account.pdf": bytes(fynbosAccount),
  "fynbos-cleaning-domain.pdf": bytes(fynbosDomain),
  "fynbos-cleaning-genuine.pdf": bytes(fynbosGenuine),
  "fynbos-cleaning-letter.pdf": bytes(fynbosLetter),
  "hadeda-couriers-account.pdf": bytes(hadedaAccount),
  "hadeda-couriers-domain.pdf": bytes(hadedaDomain),
  "hadeda-couriers-genuine.pdf": bytes(hadedaGenuine),
  "hadeda-couriers-letter.pdf": bytes(hadedaLetter),
  "karoo-stationery-account.pdf": bytes(karooAccount),
  "karoo-stationery-domain.pdf": bytes(karooDomain),
  "karoo-stationery-genuine.pdf": bytes(karooGenuine),
  "karoo-stationery-letter.pdf": bytes(karooLetter),
};
